using System.Text;

namespace PortAtlas.Core.Export;

/// <summary>
/// Formats a matrix as a Markdown document: its explanation, its column legend, then its rows as a table.
/// </summary>
public sealed class MarkdownMatrixFormatter
{
    // The matrix holds only what the audit recorded: rules written from it alone would block what runs outside that
    // period. Said in every file, since a Markdown matrix is meant to be handed to someone who did not run the audit.
    private const string ScopeNote =
        "Generated by PortAtlas from audit logs, which record the connections seen while the audit ran. A flow that did not occur during that period (monthly job, failover, backup window) is missing: check the period covered before turning the rows into rules.";

    // Characters that open an inline construct of CommonMark or end a table cell of GitHub Flavored Markdown. Escaped
    // with a backslash, they show as typed: a host, process or user name chosen by a third party must not add a link,
    // an HTML element or a column to the document.
    private static readonly char[] MarkdownSyntax = ['\\', '`', '*', '_', '[', ']', '<', '>', '|', '~', '&'];

    /// <summary>
    /// Builds the lines of the Markdown document of a matrix.
    /// </summary>
    /// <typeparam name="T">Row item of the matrix.</typeparam>
    /// <param name="description">Explanation and column legend of the matrix.</param>
    /// <param name="layout">Columns and row values of the matrix.</param>
    /// <param name="items">Rows of the matrix, in their order.</param>
    /// <returns>The lines of the document, without line ends.</returns>
    /// <exception cref="ArgumentNullException">When an argument is null.</exception>
    public IReadOnlyList<string> Format<T>(MatrixDescription description, IMatrixColumnLayout<T> layout, IReadOnlyList<T> items)
    {
        ArgumentNullException.ThrowIfNull(description);
        ArgumentNullException.ThrowIfNull(layout);
        ArgumentNullException.ThrowIfNull(items);

        var lines = new List<string>
        {
            $"# {description.Title}",
            string.Empty,
            description.Summary,
            string.Empty,
            ScopeNote,
            string.Empty,
            "## What it can be used for",
            string.Empty
        };
        lines.AddRange(description.Uses.Select(use => $"- {use}"));

        lines.AddRange([string.Empty, "## Columns", string.Empty, "| Column | Content |", "| :--- | :--- |"]);
        lines.AddRange(description.Columns.Select(column => $"| `{column.Name}` | {column.Content} |"));

        lines.AddRange([string.Empty, $"## {description.RowsHeading} ({items.Count})", string.Empty]);
        if (items.Count == 0)
        {
            lines.Add("No row passed the filters.");
            return lines;
        }

        lines.Add(TableRow(layout.ColumnNames));
        lines.Add(TableRow(layout.ColumnNames.Select(_ => "---")));
        lines.AddRange(items.Select(item => TableRow(layout.FieldsOf(item).Select(EscapeCell))));
        return lines;
    }

    private static string TableRow(IEnumerable<string> cells) => $"| {string.Join(" | ", cells)} |";

    // A line break or a tab would end the row or shift the cells: each control character becomes a space.
    private static string EscapeCell(string value)
    {
        var cell = new StringBuilder(value.Length);
        foreach (var character in value)
        {
            if (char.IsControl(character))
            {
                cell.Append(' ');
                continue;
            }

            if (Array.IndexOf(MarkdownSyntax, character) >= 0)
            {
                cell.Append('\\');
            }

            cell.Append(character);
        }

        return cell.ToString();
    }
}
